package com.hs.listing.model; import com.hs.listing.model.constant.*; import com.hs.listing.model.constant.ListingEnums.*; import jakarta.persistence.*; import lombok.*;
@Entity @Table(name="listing_room_details") @Getter @Setter @NoArgsConstructor public class ListingRoomDetail { @Id private String listingId; @MapsId @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="listing_id") private Listing listing; @Column(name="room_code") private String roomCode; @Column(name="floor_number") private Integer floorNumber; @Enumerated(EnumType.STRING) @Column(name="restroom_type",nullable=false) private RestroomType restroomType; @Enumerated(EnumType.STRING) @Column(name="kitchen_type") private KitchenType kitchenType; @Column(name="has_window") private Boolean hasWindow; @Column(name="has_balcony") private Boolean hasBalcony; @Column(name="has_mezzanine") private Boolean hasMezzanine; @Enumerated(EnumType.STRING) @Column(name="furnishing_status",nullable=false) private FurnishingStatus furnishingStatus; @Enumerated(EnumType.STRING) @Column(name="access_type") private ListingEnums.AccessType accessType; @Enumerated(EnumType.STRING) @Column(name="access_hours_type") private AccessHoursType accessHoursType; @Enumerated(EnumType.STRING) @Column(name="electric_meter_type") private MeterType electricMeterType; @Enumerated(EnumType.STRING) @Column(name="water_meter_type") private MeterType waterMeterType; @Column(name="max_occupants",nullable=false) private Integer maxOccupants; @Column(name="max_vehicles") private Integer maxVehicles; @Enumerated(EnumType.STRING) @Column(name="parking_policy") private ParkingPolicy parkingPolicy; }
